pyq_focus = [
 "Is unit se NET mein sabse zyada theorist-work matching aata hai: kaun sa book kisne likha (Of Grammatology - Derrida, Orientalism - Said, Gender Trouble - Butler).",
 "Coined terms bahut puchhe jaate hain: differance, episteme, interpellation, gynocriticism, ecriture feminine, intertextuality, hybridity, historiographic metafiction, heteroglossia, chronotope.",
 "Famous quotes ka source pucha jaata hai: 'There is nothing outside the text', 'incredulity toward metanarratives', 'Always historicize!', 'The subaltern cannot speak'.",
 "Chronology questions aate hain: books ko saal ke hisaab se arrange karna (Second Sex 1949 se Gender Trouble 1990 tak). Har major book ka saal yaad rakho.",
 "Assertion-Reason mein concept ki samajh check hoti hai, jaise Saussure ka arbitrary sign, Lacan ka unconscious as language, Althusser ka ISA.",
 "Feminism aur Postcolonialism se har saal 2-3 sawaal pakke hain; Showalter ke 3 phases, Spivak, Bhabha, Fanon, Ngugi ko achhe se padho.",
 "Naye topics (Ecocriticism, Queer theory, Postmodernism) se 2018 ke baad sawaal badhe hain: Rueckert, Glotfelty, Buell, Sedgwick, de Lauretis, Baudrillard.",
 "Preparation tip: har theorist ke liye ek card banao - 2 books + saal + 1 coined term + 1 quote. Is file ke works, quotes aur people lists ko roz revise karo.",
]

easy = [
 {"title":"Structuralism and Narratology: Saussure, Levi-Strauss, Jakobson, Genette",
  "story":"Socho cricket ke rules. Ek akela ball ka koi matlab nahi, matlab tab banta hai jab poora game ka system ho. Saussure ne kaha bhasha bhi aisi hi hai: 'kutta' shabd aur asli kutte ka rishta manmana (arbitrary) hai, aur har shabd ka matlab doosre shabdon se farak se aata hai. Langue poora system hai, parole ek baar bola gaya vaakya. Levi-Strauss ne yahi trick myths par lagayi (mythemes), Propp ne folk tales ke 31 functions gine, aur Genette ne kahani sunane ke tareeqe (focalization, order, voice) ka hisaab lagaya.",
  "trick":"'SaLe JaGe Pro' - Saussure 1916 (Course), Levi-Strauss 1958 (Structural Anthropology), Jakobson 1956/1960, Genette 1972 (Narrative Discourse), Propp 1928 (31 functions). Todorov ne 'narratology' naam rakha - 'Todo-rov ne naam todd ke rakha'."},
 {"title":"Roland Barthes: from structuralism to post-structuralism",
  "story":"Barthes pehle structuralist the, phir khud hi structure todne lage. Mythologies mein unhone dikhaya ki ek magazine cover par salute karta Black soldier ek 'myth' banata hai - France ki empire achhi hai. Phir 1967 mein bole 'Author mar gaya' - matlab kahani ka matlab likhne wale ki marzi se nahi, padhne wale se banta hai, jaise WhatsApp forward ka matlab har koi apne hisaab se nikalta hai. S/Z mein Balzac ki Sarrasine ko 5 codes mein toda, aur readerly (aaram se padho) vs writerly (khud matlab banao) text ka farak bataya.",
  "trick":"Barthes ka ladder: 'Myth-57, Death-67, S/Z-70, Pleasure-73, Camera-80'. S/Z ke 5 codes: 'HP SSC' - Hermeneutic, Proairetic, Semic, Symbolic, Cultural."},
 {"title":"Post-structuralism and Deconstruction: Jacques Derrida",
  "story":"Dictionary mein ek shabd ka matlab dekho, wahan aur shabd milte hain, unka matlab dekho to aur shabd - matlab kabhi final nahi hota. Derrida ne isse 'differance' kaha: matlab alag bhi hota hai aur aage tal bhi jaata hai. Unhone kaha Western philosophy speech ko writing se upar rakhti hai (logocentrism) aur aise hi 'man upar, woman neeche' jaise jode banati hai. Deconstruction in jodon ko ulat-palat karke dikhata hai ki text khud apne khilaaf bolta hai. 1966 mein Johns Hopkins wala paper aur 1967 ki teen books se yeh shuru hua.",
  "trick":"'66 mein khel (Play), 67 mein teen kitaabein (Grammatology, Writing and Difference, Speech and Phenomena)'. Differance mein 'a' sirf likhne mein dikhta hai, bolne mein nahi - 'a = andar chhupa'."},
 {"title":"Michel Foucault: discourse, power, knowledge",
  "story":"School mein teacher sab bachchon ko dekh sakti hai, par bachche nahi jaante kab dekha ja raha hai, isliye sab khud hi seedhe baithte hain. Foucault ne isse Panopticon kaha - power sirf danda nahi, woh hamein andar se discipline sikhati hai. Unke liye power aur knowledge saath chalte hain: jo 'pagal', 'mareez' ya 'apradhi' kehlata hai, woh discourse banata hai. Har yug ka apna knowledge ka dhaancha hota hai jise woh episteme kehte hain.",
  "trick":"Foucault ka time-table: 'Madness 61, Clinic 63, Order 66, Archaeology 69, Discipline 75, Sexuality 76' - 'Pagal-Doctor-Order-Khudai-Jail-Sex'."},
 {"title":"Psychoanalytic criticism: Freud, Jung, Bloom",
  "story":"Freud kehte the hamare mann mein ek chhupa basement hai - unconscious - jahan dabaye hue sapne aur ichchhayein rehti hain. Sapne unhe chhupa ke dikhate hain: condensation (kai cheezein ek mein) aur displacement (dhyan doosri cheez par). Jung ne kaha poori insaaniyat ka ek common basement hai - collective unconscious - jismein archetypes hain jaise hero, maa, shadow. Harold Bloom ne kaha bada kavi apne purane guru-kavi se darr kar unhe jaan-bujh kar galat padhta hai - The Anxiety of Influence.",
  "trick":"Freud = 'Dream 1900', Jung = 'Jungle of Archetypes', Bloom 1973 ke 6 ratios: 'CTK DAA' - Clinamen, Tessera, Kenosis, Daemonization, Askesis, Apophrades."},
 {"title":"Jacques Lacan",
  "story":"Chhota bachcha pehli baar mirror mein apne aap ko dekh kar khush hota hai - 'yeh main hoon, poora aur perfect!' - par asal mein woh abhi theek se chal bhi nahi sakta. Lacan ne isse mirror stage kaha: hamara 'main' ek galatfehmi se shuru hota hai. Phir bachcha bhasha seekhta hai aur Symbolic order mein aata hai, jahan papa ka niyam (Name-of-the-Father) chalta hai. Lacan ke liye unconscious bhi ek bhasha ki tarah bana hai.",
  "trick":"Teen orders ka 'ISR' = 'Imaginary, Symbolic, Real' - socho 'ISRO' ka rocket bina O ke. Mirror stage 1936/1949, Ecrits 1966."},
 {"title":"Marxist criticism: Althusser, Macherey, Williams and the Frankfurt School",
  "story":"Marx ne kaha paisa aur kaam (base) upar ki cheezon - kala, dharm, kanoon (superstructure) - ko shape deta hai. Althusser ne bataya ki school, family, TV jaise Ideological State Apparatuses hamein chupchaap 'achha nagrik' banate hain - jaise kisi ne 'Oye!' bola aur tum mud gaye, yahi interpellation hai. Macherey ne kaha text jo nahi bolta, woh bhi important hai. Raymond Williams ne kaha 'culture is ordinary', aur Frankfurt School ne movies-music ki 'culture industry' ki aalochna ki.",
  "trick":"'Al-ISA-70' - Althusser ka ISA essay 1970. 'Gramsci = Gram-hegemony' (sahmati se raaj). 'Benjamin ki aura kho gayi photocopy mein' (1935/36)."},
 {"title":"Marxist criticism: Terry Eagleton and Fredric Jameson",
  "story":"Eagleton British hain jinhone sabke liye Literary Theory: An Introduction (1983) likhi - unke hisaab se 'literature' koi pakki cheez nahi, logon ki pasand-napasand se banta hai. Jameson American hain jinka naara hai 'Always historicize!' - har kahani ke peeche itihaas dekho. Jameson ne postmodernism ko 'late capitalism ka cultural logic' kaha, jaise mall mein sab kuch chamkila par gehraai nahi. Unhone third-world novels ko 'national allegory' bhi kaha.",
  "trick":"'E-83, J-81' - Eagleton ki Intro 1983, Jameson ki Political Unconscious 1981. Jameson = 'Jam-history' - har cheez ko itihaas ke jam mein daalo."},
 {"title":"Reader-response and Reception theory",
  "story":"Ek hi film ko dadi, papa aur aap alag-alag tarah samajhte ho - yahi reader-response hai. Iser kehte hain text mein khaali jagah (gaps) hoti hai jo reader bharta hai. Jauss kehte hain har zamane ke padhne walon ki ek 'horizon of expectations' hoti hai. Stanley Fish kehte hain matlab akele reader se nahi, 'interpretive community' (jaise ek class ya group) se banta hai.",
  "trick":"'I-J-F' = 'Iser ke gaps, Jauss ka horizon, Fish ki community'. Rosenblatt ka 'transaction' - jaise UPI transaction, dono taraf se lena-dena."},
 {"title":"Feminist criticism: Beauvoir, Showalter, Gilbert and Gubar",
  "story":"Beauvoir ne 1949 mein kaha ladki paida nahi hoti, samaj use 'aurat' banata hai, aur aurat ko 'Other' bana deta hai. Showalter ne women's writing ke teen phase bataye - Feminine (nakal), Feminist (virodh), Female (apni pehchaan). Gilbert aur Gubar ne kaha 19th century ki lekhikaon ne apna gussa 'pagal aurat' jaise Jane Eyre ki Bertha ke zariye dikhaya. Kate Millett ne Sexual Politics mein male writers ki aalochna ki.",
  "trick":"Showalter ke phases: 'FFF = 1840-1880-1920' - 'Fashion, Fight, Freedom'. Madwoman 1979 - 'Attic mein 79 seedhiyan'."},
 {"title":"French feminism and Judith Butler",
  "story":"French feminists ne kaha bhasha khud mardana hai, isliye aurat ko apne sharir aur apni tarah se likhna chahiye - Cixous ne isse ecriture feminine kaha ('white ink' se likhna). Kristeva ne semiotic (maa jaisi lay, rhythm) aur symbolic (papa jaisa niyam) ka farak bataya. Irigaray ne kaha aurat ki sexuality ek nahi, anek hai. Judith Butler ne kaha gender roz ki acting jaisa hai - jaise roz same uniform pehen ke role nibhana - yahi performativity hai.",
  "trick":"'Cixous ki Medusa hansti hai (1975), Kristeva ki Horror (1980), Irigaray ka Speculum (1974), Butler ka Trouble (1990)'."},
 {"title":"Postcolonialism: Said, Spivak, Bhabha",
  "story":"Angrezon ne kitaabon mein 'East' ko jadui, aalsi aur rahasyamay dikhaya - Said ne kaha yeh Orient asli nahi, West ka banaya hua hai (Orientalism, 1978). Spivak ne poocha kya sabse neeche dabaya hua insaan, subaltern, apni baat keh sakta hai, aur sati ka udaharan diya. Bhabha ne kaha colonized log angrezon ki nakal karte hain par 'bilkul same nahi' - is mimicry aur hybridity se colonial power hil jaati hai. Teeno ko postcolonial theory ki 'Holy Trinity' kehte hain.",
  "trick":"'SSB = Said 78, Spivak 85/88, Bhabha 94' - jaise SSB interview, teeno pass karne padte hain."},
 {"title":"Postcolonialism: Fanon, Ngugi and others",
  "story":"Fanon Martinique ke doctor the jinhone dekha ki colonized insaan 'safed mask' pehen ke jeena seekh leta hai - Black Skin, White Masks (1952). The Wretched of the Earth (1961) mein unhone azaadi ki ladaai par likha, preface Sartre ka hai. Ngugi ne kaha apni maa-bhasha mein likho, isliye English chhod ke Gikuyu mein likhne lage - Decolonising the Mind (1986). Achebe ne Conrad ke Heart of Darkness ko racist kaha.",
  "trick":"'Fanon ke 52 masks, 61 wretched' aur 'Ngugi 86 - English ko alvida'. Empire Writes Back (1989) = 'ATG' - Ashcroft, Griffiths, Tiffin."},
 {"title":"New Historicism and Cultural Materialism",
  "story":"Shakespeare ka play padhte waqt uske zamane ke akhbaar, sarkari order, doctor ki diary bhi saath padho - yahi New Historicism hai. Greenblatt ne kaha sarkar thoda vidroh hone deti hai taaki use control kar sake (subversion-containment). Montrose ne kaha 'texts ki historicity aur history ki textuality'. British Cultural Materialism (Dollimore, Sinfield) Marxist hai aur kehta hai purane text ko aaj ki rajneeti ke liye use karo.",
  "trick":"'Greenblatt 82 mein naam, Political Shakespeare 85 mein kaam' - America = containment, Britain = dissidence."},
 {"title":"Ecocriticism",
  "story":"Jaise hum kahani mein hero-heroine ko dekhte hain, ecocriticism nadi, jungle, mausam aur jaanwaron ko dekhta hai. Rueckert ne 1978 mein yeh shabd banaya, aur Glotfelty ne kaha yeh literature aur physical environment ke rishte ka adhyayan hai. Buell ne Thoreau par likha, Jonathan Bate ne Wordsworth ko 'green' kavi dikhaya. Amitav Ghosh ne poocha ki climate change hamare novels mein kyun nahi dikhta.",
  "trick":"'R-78, G-96' - Rueckert ne naam rakha, Glotfelty ne Reader banaya. 'Naess = Deep, d'Eaubonne = Eco-feminism'."},
 {"title":"Postmodernism: Lyotard, Baudrillard, Hutcheon",
  "story":"Pehle log maante the ek badi kahani sab samjha degi - jaise progress ya science. Lyotard ne kaha postmodern insaan aisi grand stories par shak karta hai aur chhoti-chhoti kahaniyon par jeeta hai. Baudrillard ne kaha aaj copy asli se zyada asli lagti hai - jaise Instagram filter wali photo - yahi hyperreality hai. Hutcheon ne woh novels pehchane jo itihaas likhte hue khud par hanste hain - historiographic metafiction, jaise Midnight's Children.",
  "trick":"'L-79, B-81, H-88' - Lyotard ki Condition, Baudrillard ka Simulacra, Hutcheon ki Poetics. 'Disneyland nakli dikhaya taaki baaki America asli lage'."},
 {"title":"Mikhail Bakhtin and the Bakhtin Circle",
  "story":"Ek shaadi mein chacha, mama, dost, pandit sab apni-apni bhasha bolte hain - novel bhi aisa hi hai, Bakhtin ne isse heteroglossia kaha. Dostoevsky ke novels mein har character ki awaaz azaad hai, author sab par haavi nahi - yeh polyphony hai. Holi jaisa tyohaar jismein raja-praja ka farak mit jaata hai - Bakhtin isse carnivalesque kehte hain (Rabelais par). Time aur space ka jod chronotope hai, jaise 'road' kahani mein milne ka time-space.",
  "trick":"'Dosto 29/63 = Polyphony, Rabelais 65 = Carnival, Dialogic 75/81 = Heteroglossia + Chronotope'. Bakhtin = 'Baat-chit' (dialogism)."},
 {"title":"Queer theory",
  "story":"Samaj maan ke chalta hai ki har koi straight hai aur ladka-ladki ka role fix hai - isse heteronormativity kehte hain. Queer theory kehti hai sexuality aur gender fixed label nahi, samaj ke banaye hue hain. Foucault ne kaha 'homosexual' ek identity ke roop mein 19th century mein bana. Sedgwick ne male dosti ke andar ke rishton (homosocial desire) aur 'closet' ki baat ki, aur Teresa de Lauretis ne 1990 mein 'queer theory' naam diya.",
  "trick":"'Sedgwick 85 Between Men, 90 Closet; de Lauretis 90/91 naam; Butler 90 Trouble' - 1990 queer theory ka janam saal."},
]
